import React from "react";
import Header from "./components/Header";
import Hero from "./components/Hero";
import Service from "./components/Service";
import Project from "./components/Project";

const Home = () => {
    return (
        <>
            <Header />
            <Hero/>
            <Service/>
            <Project/>
            <section id="about" style={{ height: "100vh", background: "#111", color: "#fff" }}>
                <h1>About Section</h1>
            </section>
            <section id="contact" style={{ height: "100vh", background: "#1e1e1e", color: "#fff" }}>
                <h1>Contact Us Section</h1>
            </section>
        </>
    )
}

export default Home
